#!/usr/bin/env python3
"""Further honorific and situational appropriateness checks, batch 51."""
import json,html
import quiz_audit as qa
import v9_apply_batch1 as b
prior=json.loads((b.OUT/'changes.json').read_text());assert len(prior)==1093
_,Q,A=qa.audit(str(b.DST));D=json.loads((b.OUT/'decisions.json').read_text());extra=[]
def rewrite(qid,key,stem,opts,exps,reason,verdicts):
 assert len(opts)==len(exps)==len(verdicts)==4 and int(A['A_'+qid[2:]]['ans'])==key
 for field,old,new in [('stem',[Q[qid]['stem']],[stem]),('options',Q[qid]['opts'],opts),('explanations',A['A_'+qid[2:]]['txt'],exps)]:
  for i,(before,after) in enumerate(zip(old,new)):
   if html.unescape(before)==after:continue
   extra.append(dict(id=qid,field=field,index=None if field=='stem' else i,before=html.unescape(before),after=after,reason=reason,sources=['S04'],applied=True,before_version='第50修正バッチ作業稿'))
 D[qid].update(status='確認済み',fixes_applied=True,independent_answer=key,sources=['S04'],option_verdicts=verdicts,reason=reason,stem_review='指針の記述と事例の明示条件を照合し4肢を独立判定。',explanation_review='全4解説を照合し、未検証の効果・他の評価体系への一括帰属を撤去。',unresolved='',multiple_correct_risk='なし：指定条件に適合するのは正答のみ',no_correct_risk='なし：独立正答'+str(key))
rewrite('Q_4_090',1,
 'ビジネス場面での敬語の選択について、文化審議会『敬語の指針』の考え方に照らし、最も適切なものを一つ選びなさい。',
 ['相手との関係、その場の状況、依頼で相手に掛ける負担などを踏まえ、敬語や前置きの表現を選ぶ。','ビジネスの依頼では、相手の負担を意識した前置きはどの場面でも不要であり、すべて省く。','社内の上司に取引先の人について話す場合、上司への丁寧さを表すには、取引先の人の行為を必ず謙譲語Ⅱの「参る」で表さなければならない。','敬語の活用形が正しければ、相手との関係や場面を考慮する必要はない。'],
 ['指針は相手や場面に応じた選択を重視し、依頼では相手の負担を意識した前置きや婉曲的な言い方も示しています。','指針は「すみませんが」などの前置きを、負担への配慮を示す例として説明します。一方、いつも依頼し合う関係などでは簡潔な表現で十分な場合もあります。','聞き手への丁寧さと、話題の人物を立てる働きは区別します。謙譲語Ⅱは、立てるべき人物の行為には使えず、上司への丁寧さを表すために取引先の行為を必ず「参る」にするという規則はありません。','敬語の形式が正しくても、その場面や相手に合うかは別に考える必要があります。指針は具体的な人間関係や依頼の条件に応じた選択を示しています。'],
 '社内の上司への報告と社外への自社上司の報告を混同する解説を撤去。ビジネスメールの未照合規範も撤去し、指針の人物関係・場面・依頼の負担に限定。',
 ['指針の相手と場面による選択に一致','前置きへの一律否定は不一致','聞き手と動作主の働きを混同','形式と場面適切性を混同'])
rewrite('Q_4_092',1,
 'ビジネス場面で、普段は仕事を頼み合わない同僚に、急に負担の掛かる作業を依頼する。文化審議会『敬語の指針』が示す依頼時の配慮に照らし、最も適切な説明を一つ選びなさい。',
 ['「忙しいところ申し訳ないけど」などの前置きを添え、相手の負担を意識していることを示す方法がある。','「お願いします」という敬語さえ使えば、突然書類を置いて立ち去っても、相手への配慮を考える必要はない。','相手が同僚であれば、急な仕事の依頼でも、その負担を考慮する必要はない。','依頼の表現は長いほど常に適切なので、相手との関係にかかわらず最も回りくどい表現を選ぶ。'],
 ['指針第3章5は、突然の依頼について、前置きや婉曲的な表現で相手の負担への意識を示すことを説明しています。これは必ず依頼が受け入れられるという意味ではありません。','指針は、前置きなく突然頼むことについて、行動と言語表現の両方から問題を指摘しています。敬語の形式だけで配慮が十分とはできません。','指針の例は同僚への依頼であり、その場合にも相手への負担を考慮しています。','指針は、指示や依頼を簡潔に行える場面では回りくどい表現を用いない方がよいことも示しています。長さだけで適切さは決まりません。'],
 '特定の返答の印象やクッション語の効果を全場面に固定しない。依頼の負担・関係を指定し、指針第3章5の前置きと場面選択に限定。',
 ['指針の前置きによる負担意識の例に一致','行動と前置きを考慮しない点が不一致','同僚にも負担を考慮する本文に不一致','簡潔さを選べる本文に不一致'])
rewrite('Q_5_099',2,
 '文化審議会『敬語の指針』を踏まえ、学習者が場面に応じて敬語を選ぶ練習を計画する。計画の考え方として、最も適切なものを一つ選びなさい。',
 ['活用形の正誤だけを扱い、誰が誰に何を頼むのかは、表現の選択に関係しないと説明する。','話し手・聞き手・話題の人物の関係や、依頼の負担などの条件を示し、その条件に合う表現を検討させる。','敬語を使う場面では、相手との親しさやその場の状況は考えなくてよいと説明する。','身内について話す表現は、全国共通語でも各地の方言でもすべて同じであるとして扱う。'],
 ['指針は、形式だけでなく人間関係や場面に応じた選択を示しています。場面を無関係とする説明は、その考え方に合いません。','指針の社内外の使い分けや依頼の負担の例に対応した練習です。この判断は計画と指針の整合性についてであり、特定の指導法の効果を保証するものではありません。','指針は相手や場面を踏まえた主体的な選択を重視します。親しさや状況を無視する説明にはなっていません。','指針第3章7は、全国共通語と方言敬語で、身内への敬語などの意味や働きが異なる場合を説明しています。'],
 '社会文化能力・社会言語能力・語用能力の同一視とCEFR/ACTFLの評価観点の一括帰属を撤去。同じ場面適切性の練習領域を保ち、指針との整合性の判断に限定。',
 ['関係と場面の役割を否定','指針の場面条件を用いる計画に適合','親しさや状況を除外し不一致','方言敬語との差を否定し不一致'])
rewrite('Q_O_014',4,Q['Q_O_014']['stem'],Q['Q_O_014']['opts'],
 ['このケースの課題は、同じ尊敬語の形を社内外で使ったことです。活用の反復だけを行い場面に触れない方針は、場面の違いに気づかせるという設問の目的に対応しません。','ケースでは教師が場面に応じた表現の選択を説明しています。文法形式の誤りではないことだけを理由に扱わない方針は、設問の指導目的に対応しません。','待遇表現を扱わない方針では、今回の場面による選択の違いを学習者が検討する機会を設けられません。','社内の同僚に伝える場面と、取引先に伝える場面の比較は、ケースの課題と設問の目的に対応します。指針も社内外で立てる対象を変える例を示しています。本人の在席・不在だけで判断するものではありません。'],
 '第14修正バッチの社内外ケースと選択肢を再確認。既改訂の場面条件を維持し、指導の意義を一般化せず、設問目的・ケース課題に対応する活動として判定。指針第3章2と照合。',
 ['場面に触れず今回の目的に不適合','設問の指導目的を放棄','選択の違いを扱わず目的に不適合','具体的な場面比較が目的に適合'])
rewrite('Q_M_055',4,
 '文化審議会『敬語の指針』における「〜させていただく」の基本的な使用条件について、最も適当なものを選べ。',
 ['実際によく使われる形式なので、どの場面でも必ず適切である。','「いただく」は敬語ではなく、この形式は使役形だけで構成される。','相手側や第三者の許可、行為による恩恵は、この形式の適切さを考える際に関係しない。','基本的には、自分側の行為について相手側又は第三者の許可を受け、そのことで恩恵を受けるという事実や気持ちがある場合に使われる。'],
 ['指針は、この形式には適切な場合と、あまり適切とはいえない場合があると説明しています。使用の多さだけでは適切さを判断できません。','「いただく」は謙譲語Ⅰの例です。「〜させていただく」は、使役形と敬語の要素を含む形式です。','指針は許可と恩恵という二つの条件を挙げ、その条件をどの程度満たすかによって適切さが異なると説明しています。','指針第2章の「させていただく」の節が示す基本条件と一致します。条件を満たすかのように見立てる用法や、その許容度の個人差も説明されており、形式だけで一律に判断する趣旨ではありません。'],
 'よく使われるから誤用でないという推論を撤去。指針印刷40〜41頁の許可・恩恵の基本条件、見立て用法と許容度の違いを保持して単一正答を確認。',
 ['使用頻度で適切さを保証し不一致','いただくの敬語分類を否定','基本条件の二点を否定','指針の基本条件に一致'])
(b.OUT/'changes_honorific_20261013_part2.json').write_text(json.dumps(extra,ensure_ascii=False,indent=2)+'\n');(b.OUT/'changes.json').write_text(json.dumps(prior+extra,ensure_ascii=False,indent=2)+'\n');(b.OUT/'decisions.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
print('5 questions /',len(extra),'edits')
